function update(dt) {
  if (gameOver) return;
  // Player movement
  if (keys.ArrowLeft && ship.x - ship.radius > 0) ship.x -= ship.speed;
  if (keys.ArrowRight && ship.x + ship.radius < canvas.width) ship.x += ship.speed;
  if (keys.ArrowUp && ship.y - ship.radius > 0) ship.y -= ship.speed;
  if (keys.ArrowDown && ship.y + ship.radius < canvas.height) ship.y += ship.speed;

  // Spawn asteroids/fuel
  asteroidTimer += dt;
  fuelTimer += dt;
  if (asteroidTimer > 1000) { // every second
    spawnAsteroid();
    asteroidTimer = 0;
  }
  if (fuelTimer > 3000) { // every 3 seconds
    spawnFuel();
    fuelTimer = 0;
  }

  // Update asteroids
  asteroids.forEach((a, i) => {
    a.y += a.speed;
    if (a.y - a.radius > canvas.height) asteroids.splice(i, 1);
    // collision with ship
    const dx = a.x - ship.x;
    const dy = a.y - ship.y;
    const dist = Math.hypot(dx, dy);
    if (dist < a.radius + ship.radius) gameOver = true;
  });

  // Update fuels
  fuels.forEach((f, i) => {
    f.y += f.speed;
    if (f.y - f.radius > canvas.height) fuels.splice(i, 1);
    const dx = f.x - ship.x;
    const dy = f.y - ship.y;
    const dist = Math.hypot(dx, dy);
    if (dist < f.radius + ship.radius) {
      fuel += 20; // add fuel seconds
      fuels.splice(i, 1);
    }
  });

  // Decrease fuel over time
  fuel -= dt / 1000;
  if (fuel <= 0) gameOver = true;
  score += dt / 1000;
}

