  asteroids.forEach((a, i) => {
    a.y += a.speed;
    if (a.y - a.radius > canvas.height) asteroids.splice(i, 1);
    // collision with ship (triangle approx using ship.size)
    const dx = a.x - ship.x;
    const dy = a.y - ship.y;
    const dist = Math.hypot(dx, dy);
    if (dist < a.radius + ship.size) gameOver = true;
  });

  // Update fuels
  fuels.forEach((f, i) => {
